<template>
  <!-- Port of XMCL Me.vue / MeProfilePanel / UserAccountSwitcher layout. -->
  <div class="xmcl-account-page" :class="{ 'pcl-account-page--classic': pcl }"><aside class="xmcl-account-nav"><div class="xmcl-account-avatar"><span v-if="activeAccount?.profile?.skin?.url" class="account-face" :style="skinFaceStyle(activeAccount.profile.skin.url)" aria-hidden="true"></span><q-icon v-else name="person" size="38px"/></div><strong>{{ t('xmcl.account.center') }}</strong><button v-for="item in sections" :key="item.id" :class="{active:section===item.id}" @click="section=item.id"><q-icon :name="item.icon"/>{{ item.label }}</button></aside><main class="xmcl-account-content"><template v-if="section==='profile'"><div class="xmcl-account-header"><div><div class="eyebrow">{{ t('ui.myAccount') }}</div><h4>{{ t('xmcl.account.profileTitle') }}</h4><p>{{ t('xmcl.account.profileHint') }}</p></div><div class="row q-gutter-sm"><q-btn color="primary" :label="t('xmcl.account.addMicrosoft')" :disable="busy" @click="openLogin('microsoft')"/><q-btn v-if="offlineAccountAllowed" flat :label="t('xmcl.account.addOffline')" :disable="busy" @click="openLogin('offline')"/><q-btn flat :label="t('xmcl.account.addYggdrasil')" :disable="busy" @click="openLogin('yggdrasil')"/><q-btn flat :label="t('xmcl.account.addUnifiedPass')" :disable="busy" @click="openLogin('unified-pass')"/></div></div><AccountPanel :accounts="accounts" :busy="busy" :execute="execute" @changed="onChanged"/></template><template v-else-if="section==='presets'"><div class="xmcl-account-header"><div><div class="eyebrow">{{ t('ui.authority') }}</div><h4>{{ t('xmcl.account.yggdrasil') }}</h4><p>{{ t('xmcl.account.presetHint') }}</p></div><q-btn color="primary" :label="t('xmcl.account.addService')" @click="addPreset"/></div><q-list bordered separator class="xmcl-preset-list"><q-item v-for="preset in presets" :key="preset.name"><q-item-section><q-item-label>{{ preset.name }} <q-badge v-if="preset.builtin">{{ t('xmcl.account.builtin') }}</q-badge><q-badge v-if="preset.managedLocal" color="positive">{{ t('xmcl.account.localService') }}</q-badge></q-item-label><q-item-label caption>{{ preset.managedLocal ? t('xmcl.account.managedLocal') : `${preset.authUrl} · ${preset.sessionUrl}` }}</q-item-label></q-item-section><q-item-section side><q-btn v-if="!preset.builtin" flat :label="t('common.edit')" :disable="busy" @click="editPreset(preset)"/><q-btn v-if="!preset.builtin" flat color="negative" :label="t('common.delete')" :disable="busy" @click="removePreset(preset)"/></q-item-section></q-item><q-item v-if="!presets.length"><q-item-section class="text-grey-5">{{ t('xmcl.account.noPresets') }}</q-item-section></q-item></q-list></template><template v-else><div class="xmcl-account-header"><div><div class="eyebrow">{{ t('ui.accountTools') }}</div><h4>{{ t('xmcl.account.toolsTitle') }}</h4><p>{{ t('xmcl.account.toolsHint') }}</p></div></div><div class="row q-gutter-sm"><q-btn color="primary" :label="t('xmcl.account.refreshAll')" :disable="busy" @click="refreshAll"/><q-btn outline :label="t('xmcl.account.installAuth')" :disable="busy" @click="installAuthlib"/><q-btn flat :label="t('xmcl.account.checkAuth')" :disable="busy" @click="checkAuthlib"/></div><div v-if="helper" class="text-caption text-grey-5 q-mt-sm">{{ t('xmcl.account.authComponent') }}：{{ helper.installed ? t('xmcl.account.installed', { version: helper.version || '' }) : t('xmcl.account.notInstalled') }}<span v-if="helper.path"> · {{ helper.path }}</span></div><q-list bordered separator class="q-mt-lg"><q-item v-for="a in accounts" :key="a.internalId || a.id"><q-item-section>{{ a.profileName || a.displayName }}</q-item-section><q-item-section side>{{ a.stateName || t('xmcl.account.unchecked') }}</q-item-section></q-item></q-list></template><q-banner v-if="error" class="bg-red-9 q-mt-md">{{ error }}</q-banner></main><q-dialog v-model="loginShown" persistent><q-card class="login-card text-white"><q-card-section><div class="eyebrow">{{ t('ui.accountLogin') }}</div><div class="text-h6">{{ loginTitle }}</div><p class="text-caption text-grey-5">{{ t('xmcl.account.loginHint') }}</p></q-card-section><q-card-section><q-input v-if="loginType==='yggdrasil' || loginType==='unified-pass'" v-model="loginForm.username" dark outlined :label="t('xmcl.account.username')" autofocus class="q-mb-md"/><q-input v-if="loginType==='offline'" v-model="loginForm.username" dark outlined :label="t('xmcl.account.offlinePlayer')"/><template v-if="loginType==='yggdrasil'"><q-select v-model="loginForm.presetName" dark outlined :options="presets" option-label="name" option-value="name" emit-value map-options :label="t('xmcl.account.authService')" class="q-mb-md" @update:model-value="applyPreset"/><q-input v-model="loginForm.password" dark outlined type="password" :label="t('xmcl.account.password')" class="q-mb-md"/><q-input v-if="!loginForm.managedLocal" v-model="loginForm.authUrl" dark outlined :label="t('xmcl.account.authUrl')" class="q-mb-md"/><q-input v-if="!loginForm.managedLocal" v-model="loginForm.sessionUrl" dark outlined :label="t('xmcl.account.sessionUrl')"/></template><template v-if="loginType==='unified-pass'"><q-input v-model="loginForm.password" dark outlined type="password" :label="t('xmcl.account.password')" class="q-mb-md"/><q-input v-model="loginForm.serverId" dark outlined :label="t('xmcl.account.serverId')" class="q-mb-md"/><q-input v-model="loginForm.baseUrl" dark outlined :label="t('xmcl.account.apiBase')"/></template><q-banner v-if="loginType==='microsoft'" class="bg-blue-grey-9">{{ t('xmcl.account.microsoftHint') }}</q-banner></q-card-section><q-card-actions align="right"><q-btn flat :label="t('common.cancel')" @click="loginShown=false"/><q-btn color="primary" :label="t('xmcl.account.continue')" :loading="busy" @click="submitLogin"/></q-card-actions></q-card></q-dialog>
<q-dialog v-model="presetShown"><q-card class="login-card text-white"><q-card-section><div class="eyebrow">{{ t('ui.authority') }}</div><div class="text-h6">{{ presetEditing ? t('xmcl.account.editService') : t('xmcl.account.addService') }}</div></q-card-section><q-card-section><q-input v-model="presetForm.name" dark outlined :label="t('xmcl.account.serviceName')" class="q-mb-md"/><q-input v-model="presetForm.authUrl" dark outlined :label="t('xmcl.account.authUrl')" class="q-mb-md"/><q-input v-model="presetForm.sessionUrl" dark outlined :label="t('xmcl.account.sessionUrl')" class="q-mb-md"/><q-select v-model="presetForm.tokenType" dark outlined :options="['Standard','OAuth']" :label="t('xmcl.account.tokenType')" /></q-card-section><q-card-actions align="right"><q-btn flat :label="t('common.cancel')" @click="presetShown=false"/><q-btn color="primary" :label="t('common.save')" :disable="!presetForm.name || !presetForm.authUrl || !presetForm.sessionUrl" @click="savePreset"/></q-card-actions></q-card></q-dialog></div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useI18n } from 'vue-i18n';
import AccountPanel from '../components/AccountPanel.vue';
const props=defineProps<{accounts:any[];busy:boolean;execute:(op:string,p?:Record<string,unknown>)=>Promise<any>;pcl?:boolean}>();const { t } = useI18n();const emit=defineEmits<{changed:[]}>();const section=ref('profile'),presets=ref<any[]>([]),helper=ref<any>(null),runtimeInfo=ref<any>({}),error=ref('');const activeAccount=computed(()=>props.accounts.find((account:any)=>account.default)||props.accounts[0]);const offlineAccountAllowed=computed(()=>Boolean(runtimeInfo.value?.offlineAccountAllowed)||props.accounts.some((account:any)=>account?.ownsMinecraft));
function skinFaceStyle(url:string){return {backgroundImage:`url(\"${String(url).replace(/\"/g,'%22')}\")`};}const sections=[{id:'profile',label:t('xmcl.account.profile'),icon:'person'},{id:'presets',label:t('xmcl.account.services'),icon:'dns'},{id:'tools',label:t('xmcl.account.tools'),icon:'build'}];
const loginShown=ref(false),loginType=ref('microsoft'),loginForm=ref<any>({username:'',password:'',authUrl:'',sessionUrl:'',serverId:'',baseUrl:'',presetName:'',managedLocal:false,sourceName:'',tokenType:'Standard',authenticateEndpoint:'',refreshEndpoint:'',validateEndpoint:'',profileEndpoint:'',oauthTokenEndpoint:''});const presetShown=ref(false),presetEditing=ref<any>(null),presetForm=ref<any>({name:'',authUrl:'',sessionUrl:'',tokenType:'Standard'});const loginTitle=computed(()=>({microsoft:t('xmcl.account.loginMicrosoft'),offline:t('xmcl.account.addOffline'),yggdrasil:t('xmcl.account.loginYggdrasil'),'unified-pass':t('xmcl.account.loginUnifiedPass')} as any)[loginType.value]||t('xmcl.account.loginAccount'));
function applyPreset(name:string){const preset=presets.value.find((p:any)=>p.name===name);if(!preset)return;Object.assign(loginForm.value,{authUrl:preset.authUrl||'',sessionUrl:preset.sessionUrl||'',sourceName:preset.sourceName||preset.name||'',tokenType:preset.tokenType||'Standard',managedLocal:Boolean(preset.managedLocal),authenticateEndpoint:preset.authenticateEndpoint||'',refreshEndpoint:preset.refreshEndpoint||'',validateEndpoint:preset.validateEndpoint||'',profileEndpoint:preset.profileEndpoint||'',oauthTokenEndpoint:preset.oauthTokenEndpoint||''});}
function openLogin(type:string){if(type==='offline'&&!offlineAccountAllowed.value)type='microsoft';const preset=presets.value.find((p:any)=>!p.builtin)||presets.value[0];loginType.value=type;loginForm.value={username:'',password:'',authUrl:'',sessionUrl:'',serverId:'',baseUrl:'',presetName:preset?.name||'',managedLocal:false,sourceName:'',tokenType:'Standard',authenticateEndpoint:'',refreshEndpoint:'',validateEndpoint:'',profileEndpoint:'',oauthTokenEndpoint:''};if(type==='yggdrasil'&&preset)applyPreset(preset.name);loginShown.value=true;}
async function submitLogin(){try{const p:any={type:loginType.value};if(loginType.value==='microsoft'){}else if(loginType.value==='yggdrasil'){const {presetName,...form}=loginForm.value;Object.assign(p,form);}else Object.assign(p,loginForm.value);await props.execute('account.login',p);loginShown.value=false;emit('changed');}catch(e){error.value=String(e);}}
function onChanged(){emit('changed');}
function accountRef(account:any){return String(account?.internalId || account?.id || account?.profileName || '');}
async function loadPresets(){try{const r=await props.execute('account.preset.list');presets.value=Array.isArray(r)?r:[];}catch(e){error.value=String(e);}}
async function refreshAll(){for(const account of props.accounts)try{await props.execute('account.refresh',{account:accountRef(account)});}catch(e){error.value=String(e);}emit('changed');}
function editPreset(p:any){presetEditing.value=p;presetForm.value={name:p.name||'',authUrl:p.authUrl||'',sessionUrl:p.sessionUrl||'',tokenType:p.tokenType||'Standard'};presetShown.value=true;}
function addPreset(){presetEditing.value=null;presetForm.value={name:'',authUrl:'',sessionUrl:'',tokenType:'Standard'};presetShown.value=true;}
async function savePreset(){try{const p:any={...presetForm.value};if(presetEditing.value){await props.execute('account.preset.edit',{originalName:presetEditing.value.name,...p,authenticateEndpoint:presetEditing.value.authenticateEndpoint,refreshEndpoint:presetEditing.value.refreshEndpoint,validateEndpoint:presetEditing.value.validateEndpoint,profileEndpoint:presetEditing.value.profileEndpoint,oauthTokenEndpoint:presetEditing.value.oauthTokenEndpoint});}else await props.execute('account.preset.add',p);presetShown.value=false;await loadPresets();}catch(e){error.value=String(e);}}
async function removePreset(p:any){try{await props.execute('account.preset.remove',{name:p.name,confirm:true});await loadPresets();}catch(e){error.value=String(e);}}
async function checkAuthlib(){try{helper.value=await props.execute('authentication.helper.status',{helper:'authlib-injector'});}catch(e){error.value=String(e);}}
async function installAuthlib(){try{await props.execute('authentication.helper.install',{helper:'authlib-injector'});await checkAuthlib();}catch(e){error.value=String(e);}}
onMounted(() => { void loadPresets(); void loadRuntime(); });
async function loadRuntime(){try{runtimeInfo.value=await props.execute('runtime.info',{});}catch{runtimeInfo.value={};}}
</script>
<style scoped>.login-card{width:520px;max-width:94vw;background:rgba(31,31,40,.96)!important;border:1px solid rgba(255,255,255,.12);border-radius:20px}.login-card :deep(.q-btn){text-transform:none}.xmcl-account-page{display:flex;min-height:680px;max-width:1250px;margin:0 auto}.xmcl-account-nav{width:250px;min-width:250px;padding:30px 18px;display:flex;flex-direction:column;align-items:stretch;gap:5px;border-right:1px solid rgba(255,255,255,.1)}.xmcl-account-avatar{width:76px;height:76px;border-radius:24px;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#6366f1,#312e81);margin-bottom:14px;overflow:hidden}.xmcl-account-avatar .account-face{display:block;width:100%;height:100%;border-radius:inherit;background-repeat:no-repeat;background-size:800% 800%;background-position:14.2857% 14.2857%}.xmcl-account-nav strong{font-size:18px;margin-bottom:18px}.xmcl-account-nav button{display:flex;align-items:center;gap:10px;padding:12px;border:0;border-radius:10px;background:transparent;color:rgba(255,255,255,.65);text-align:left;cursor:pointer}.xmcl-account-nav button:hover,.xmcl-account-nav button.active{background:rgba(129,140,248,.2);color:#fff}.xmcl-account-content{flex:1;min-width:0;padding:30px}.xmcl-account-header{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:24px}.xmcl-account-header h4{margin:4px 0;font-size:26px}.xmcl-account-header p{margin:0;color:rgba(255,255,255,.55)}.eyebrow{font-size:11px;letter-spacing:.14em;color:#a5b4fc;font-weight:700}.xmcl-preset-list{max-width:900px}@media(max-width:800px){.xmcl-account-page{display:block}.xmcl-account-nav{width:auto;min-width:0;border-right:0;border-bottom:1px solid rgba(255,255,255,.1);flex-direction:row;align-items:center;overflow:auto}.xmcl-account-avatar,.xmcl-account-nav strong{display:none}.xmcl-account-content{padding:20px 12px}.xmcl-account-header{display:block}.xmcl-account-header .row{margin-top:14px}}
.pcl-account-page--classic{color:#31485d;background:#f7f9fc}.pcl-account-page--classic .xmcl-account-nav{border-color:#dce4ec;background:#f7f9fc}.pcl-account-page--classic .xmcl-account-avatar{background:linear-gradient(135deg,#559bd0,#2f6eaa);border-radius:12px}.pcl-account-page--classic .xmcl-account-nav strong{color:#31577b}.pcl-account-page--classic .xmcl-account-nav button{color:#607488;border-radius:6px}.pcl-account-page--classic .xmcl-account-nav button:hover,.pcl-account-page--classic .xmcl-account-nav button.active{background:#dcecf8;color:#236a9f}.pcl-account-page--classic .xmcl-account-content{background:#f7f9fc}.pcl-account-page--classic .xmcl-account-header h4{color:#2f5979}.pcl-account-page--classic .xmcl-account-header p{color:#81909d}.pcl-account-page--classic .eyebrow{color:#4284b2}.pcl-account-page--classic .login-card{background:#fff!important;color:#31485d!important;border:1px solid #d5e0e8}.pcl-account-page--classic .login-card :deep(.text-grey-5){color:#81909d!important}.pcl-account-page--classic .login-card :deep(.q-field--dark .q-field__control){background:#fff}.pcl-account-page--classic .login-card :deep(.q-field--dark .q-field__native),.pcl-account-page--classic .login-card :deep(.q-field--dark .q-field__label),.pcl-account-page--classic .login-card :deep(.q-icon){color:#49677e}.pcl-account-page--classic .login-card :deep(.q-field--dark .q-field__control:before){border-color:#b9c9d6}.pcl-account-page--classic .login-card :deep(.bg-blue-grey-9){background:#f2f8fc!important;color:#698296}.pcl-account-page--classic .xmcl-preset-list{border-color:#d5e0e8}.pcl-account-page--classic .xmcl-preset-list :deep(.q-item__label){color:#49677e}.pcl-account-page--classic .xmcl-preset-list :deep(.q-item__label--caption){color:#81909d}.pcl-account-page--classic .text-grey-5{color:#81909d!important}@media(max-width:800px){.pcl-account-page--classic .xmcl-account-nav{background:#f7f9fc}}</style>
